-- Limpiar fechas fantasma en categorias/subcategorias sin oferta, para que no anulen ofertas propias de productos
UPDATE `categorias` SET `finOferta` = NULL WHERE `finOferta` IN ('0000-00-00 00:00:00','1970-01-01 00:00:00') AND (`oferta` IS NULL OR `oferta` = 0 OR `oferta` = '');
UPDATE `subcategorias` SET `finOferta` = NULL WHERE `finOferta` IN ('0000-00-00 00:00:00','1970-01-01 00:00:00');
UPDATE `categorias` SET `fechaInicioOferta` = NULL WHERE `fechaInicioOferta` IN ('0000-00-00 00:00:00','1970-01-01 00:00:00');
UPDATE `subcategorias` SET `fechaInicioOferta` = NULL WHERE `fechaInicioOferta` IN ('0000-00-00 00:00:00','1970-01-01 00:00:00');

-- Verificacion categorias activas
SELECT id, nombre, oferta, etiquetaOferta, finOferta FROM `categorias` WHERE `oferta` > 0;
